-- ============================================================
-- ALTER: widen project_code to VARCHAR(64)
-- Project codes are now generated by GlobalService::generateProjectCode() as
--   "<year>-<rc_id>-<prog3>-<subprog4>-<series4>", e.g. "2026-013-003-0001-0001"
-- which is 22 characters or more (longer for ids like "R01A"). fims.project.project_code and every column that
-- copies it were declared VARCHAR(20), so creating a project (Budget Request form,
-- "type a name that doesn't exist yet") failed with
--   SQLSTATE[22001]: value too long for type character varying(20)
-- Old short codes ("PRJ-0001") are untouched and keep working.
--
-- fims.project.project_code is the primary key; every other column below is a
-- foreign key to / copy of it, so all are widened to the same VARCHAR(64) (the width of
-- program_code and sub_program_code, see "11 - program_code_widen_child_columns.sql"):
--   fims.project             project_code
--   fims.budget_req_project  project_code
--   fims.budget_req          project_code
--   fims.purchase_orders     project_code
--   fims.chart_of_accounts   project_code
--   fims.budget_allocation   project_code
--
-- Widening a VARCHAR is a metadata-only change: no table rewrite, existing data and
-- foreign keys are untouched. Idempotent — a column that is missing, or already 64+
-- characters wide, is skipped — so it is safe to run any number of times.
-- ============================================================
DO $$
DECLARE
    col RECORD;
BEGIN
    FOR col IN
        SELECT c.table_name, c.column_name
        FROM information_schema.columns c
        WHERE c.table_schema = 'fims'
          AND c.column_name = 'project_code'
          AND c.table_name IN (
                'project',
                'budget_req_project',
                'budget_req',
                'purchase_orders',
                'chart_of_accounts',
                'budget_allocation'
          )
          AND c.character_maximum_length IS NOT NULL
          AND c.character_maximum_length < 64
    LOOP
        EXECUTE format('ALTER TABLE fims.%I ALTER COLUMN %I TYPE VARCHAR(64)', col.table_name, col.column_name);
        RAISE NOTICE 'Widened fims.%.% to VARCHAR(64)', col.table_name, col.column_name;
    END LOOP;
END
$$;
